#include <stdio.h>
#include <stdlib.h>

void findIntersection(int arr1[], int size1, int arr2[], int size2, int **intersection, int *size3);

int main() {
    int arr1[] = {1, 2, 3, 4, 5};
    int size1 = sizeof(arr1) / sizeof(arr1[0]);

    int arr2[] = {3, 4, 5, 6, 7};
    int size2 = sizeof(arr2) / sizeof(arr2[0]);

    int *intersection = NULL;
    int size3 = 0;

    findIntersection(arr1, size1, arr2, size2, &intersection, &size3);

    if (intersection != NULL) {
        printf("Intersection: ");
        for (int i = 0; i < size3; i++) {
            printf("%d ", intersection[i]);
        }
        printf("\n");

        // Free the dynamically allocated memory
        free(intersection);
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}

void findIntersection(int arr1[], int size1, int arr2[], int size2, int **intersection, int *size3) {
    *size3 = 0;
    int maxSize = size1 > size2 ? size1 : size2;
    *intersection = (int *)malloc(maxSize * sizeof(int));
    if (*intersection == NULL) {
        return; // Handle memory allocation failure
    }

    for (int i = 0; i < size1; i++) {
        for (int j = 0; j < size2; j++) {
            if (arr1[i] == arr2[j]) {
                (*intersection)[(*size3)++] = arr1[i];
                break;
            }
        }
    }
}
